set local pg_show_plans.is_enabled=off;
set local jit=off;
set local work_mem='4MB';
do $calendar_scope_guard$ begin if current_database()<>'cloudtms_test_clone' or not exists(select 1 from private.cloudtms_database_identity where singleton and environment='TEST') or not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='LEGACY' and owner_epoch=1) or exists(select 1 from private.cloudtms_database_releases where status='APPLYING') then raise exception 'CHECKLIST_CALENDAR_TEST_SCOPE_REFUSED'; end if; if to_regprocedure('private.weekly_source_checklist_client_calendar_v1(uuid,date)') is not null or exists(select 1 from public.clients where id=any(array['e3140000-0000-4000-8000-000000000001','e3140000-0000-4000-8000-000000000002','e3140000-0000-4000-8000-000000000003','e3140000-0000-4000-8000-000000000004','e3140000-0000-4000-8000-000000000005','e3140000-0000-4000-8000-000000000006','e3140000-0000-4000-8000-000000000007']::uuid[])) or exists(select 1 from public.client_settings where id=any(array['e3141000-0000-4000-8000-000000000001','e3141000-0000-4000-8000-000000000002','e3141000-0000-4000-8000-000000000003','e3141000-0000-4000-8000-000000000004','e3141000-0000-4000-8000-000000000005','e3141000-0000-4000-8000-000000000006','e3141000-0000-4000-8000-000000000007']::uuid[]) or client_id=any(array['e3140000-0000-4000-8000-000000000001','e3140000-0000-4000-8000-000000000002','e3140000-0000-4000-8000-000000000003','e3140000-0000-4000-8000-000000000004','e3140000-0000-4000-8000-000000000005','e3140000-0000-4000-8000-000000000006','e3140000-0000-4000-8000-000000000007']::uuid[])) then raise exception 'CHECKLIST_CALENDAR_FIXTURE_NOT_VACANT'; end if; end $calendar_scope_guard$;
select encode(pg_catalog.sha256(pg_catalog.convert_to(pg_get_functiondef('private._contract_settings_effective_core_v1(uuid,uuid,date,text,uuid)'::regprocedure),'UTF8')),'hex') native_settings_before_sha256;
-- Calendar read only. The canonical settings owner supplies the Client weekday.
-- No Timesheet, financial, source, or application record is created here.
create or replace function private.weekly_source_checklist_client_calendar_v1(
  p_client_id uuid,p_local_today date
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare authority jsonb; weekday integer; latest_week date;
begin
  if p_client_id is null or p_local_today is null then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' using errcode='22023';
  end if;
  authority:=private._contract_settings_effective_core_v1(p_client_id,null,p_local_today,'OFFICE',null);
  if authority->>'authority_version' is distinct from 'CONTRACT_SETTINGS_AUTHORITY_V1'
    or authority->>'client_id' is distinct from p_client_id::text
    or not pg_input_is_valid(coalesce(authority#>>'{values,week_ending_weekday}',''),'integer')
    or coalesce(authority->>'authority_fingerprint','')!~'^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' using errcode='55000';
  end if;
  weekday:=(authority#>>'{values,week_ending_weekday}')::integer;
  if weekday not between 0 and 6 then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' using errcode='55000';
  end if;
  -- A week ending today has not ended yet. Walk back from yesterday.
  latest_week:=p_local_today-1-((extract(dow from p_local_today-1)::integer-weekday+7)%7);
  return jsonb_build_object('contract','WEEKLY_SOURCE_CHECKLIST_CLIENT_CALENDAR_V1',
    'client_id',p_client_id,'local_today',p_local_today,'week_ending_weekday',weekday,
    'latest_ended_week',latest_week,'authority_fingerprint',authority->>'authority_fingerprint');
end;
$function$;
alter function private.weekly_source_checklist_client_calendar_v1(uuid,date) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_checklist_client_calendar_v1(uuid,date) from public,anon,authenticated,service_role;

insert into public.clients(id,name) values ('e3140000-0000-4000-8000-000000000001','Checklist calendar fixture 0'),('e3140000-0000-4000-8000-000000000002','Checklist calendar fixture 1'),('e3140000-0000-4000-8000-000000000003','Checklist calendar fixture 2'),('e3140000-0000-4000-8000-000000000004','Checklist calendar fixture 3'),('e3140000-0000-4000-8000-000000000005','Checklist calendar fixture 4'),('e3140000-0000-4000-8000-000000000006','Checklist calendar fixture 5'),('e3140000-0000-4000-8000-000000000007','Checklist calendar fixture 6');
insert into public.client_settings(id,client_id,effective_from,week_ending_weekday) values ('e3141000-0000-4000-8000-000000000001','e3140000-0000-4000-8000-000000000001',date '2026-01-01',0),('e3141000-0000-4000-8000-000000000002','e3140000-0000-4000-8000-000000000002',date '2026-01-01',1),('e3141000-0000-4000-8000-000000000003','e3140000-0000-4000-8000-000000000003',date '2026-01-01',2),('e3141000-0000-4000-8000-000000000004','e3140000-0000-4000-8000-000000000004',date '2026-01-01',3),('e3141000-0000-4000-8000-000000000005','e3140000-0000-4000-8000-000000000005',date '2026-01-01',4),('e3141000-0000-4000-8000-000000000006','e3140000-0000-4000-8000-000000000006',date '2026-01-01',5),('e3141000-0000-4000-8000-000000000007','e3140000-0000-4000-8000-000000000007',date '2026-01-01',6);
do $calendar_native_cases$ declare fixture record; today date; expected date; actual jsonb; passed integer:=0; first_hash text; second_hash text; begin
 for fixture in select id,week_ending_weekday from public.client_settings where id=any(array['e3141000-0000-4000-8000-000000000001','e3141000-0000-4000-8000-000000000002','e3141000-0000-4000-8000-000000000003','e3141000-0000-4000-8000-000000000004','e3141000-0000-4000-8000-000000000005','e3141000-0000-4000-8000-000000000006','e3141000-0000-4000-8000-000000000007']::uuid[]) order by week_ending_weekday loop
  foreach today in array array[date '2026-10-14',date '2026-10-15',date '2026-10-18',date '2026-10-19',date '2026-10-26'] loop
   select max(day::date) into expected from generate_series(today-interval '7 days',today-interval '1 day',interval '1 day') day where extract(dow from day)::integer=fixture.week_ending_weekday;
   actual:=private.weekly_source_checklist_client_calendar_v1((select client_id from public.client_settings where id=fixture.id),today);
   if (actual->>'latest_ended_week')::date is distinct from expected or (actual->>'week_ending_weekday')::integer is distinct from fixture.week_ending_weekday or (actual->>'latest_ended_week')::date>=today then raise exception 'CHECKLIST_CALENDAR_NATIVE_CASE_FAILED'; end if; passed:=passed+1;
  end loop;
 end loop;
 first_hash:=private.weekly_source_checklist_client_calendar_v1('e3140000-0000-4000-8000-000000000001'::uuid,date '2026-10-14')->>'authority_fingerprint';
 second_hash:=private.weekly_source_checklist_client_calendar_v1('e3140000-0000-4000-8000-000000000001'::uuid,date '2026-10-14')->>'authority_fingerprint';
 if first_hash is distinct from second_hash then raise exception 'CHECKLIST_CALENDAR_FALSE_READ_REVISION'; end if;
 update public.client_settings set week_ending_weekday=1 where id='e3141000-0000-4000-8000-000000000001'::uuid;
 actual:=private.weekly_source_checklist_client_calendar_v1('e3140000-0000-4000-8000-000000000001'::uuid,date '2026-10-14');
 if actual->>'authority_fingerprint'=first_hash or actual->>'latest_ended_week'<>'2026-10-12' then raise exception 'CHECKLIST_CALENDAR_SETTINGS_CHANGE_NOT_BOUND'; end if;
 begin perform private.weekly_source_checklist_client_calendar_v1(null,date '2026-10-14'); raise exception 'CHECKLIST_CALENDAR_NULL_SCOPE_ACCEPTED'; exception when invalid_parameter_value then if sqlerrm<>'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' then raise; end if; end;
 begin perform private.weekly_source_checklist_client_calendar_v1('e3140000-0000-4000-8000-000000000002'::uuid,null); raise exception 'CHECKLIST_CALENDAR_NULL_DATE_ACCEPTED'; exception when invalid_parameter_value then if sqlerrm<>'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' then raise; end if; end;
 if has_function_privilege('service_role','private.weekly_source_checklist_client_calendar_v1(uuid,date)','EXECUTE') or has_function_privilege('authenticated','private.weekly_source_checklist_client_calendar_v1(uuid,date)','EXECUTE') or has_function_privilege('anon','private.weekly_source_checklist_client_calendar_v1(uuid,date)','EXECUTE') then raise exception 'CHECKLIST_CALENDAR_PRIVATE_ACL_FAILED'; end if;
 if passed<>35 then raise exception 'CHECKLIST_CALENDAR_NATIVE_CASES_INCOMPLETE'; end if;
 end $calendar_native_cases$;
 select jsonb_build_object('calendar_cases',35,'native_settings_owner_reused',true,'read_revision_stable',true,'actual_settings_change_bound',true,'private_acl_checked',true) case_result;
